// TK-010: p95 of a trip pick (trips.create -> status ready) on the local Meteor :3200 started with AREA_SOURCE=coords,
// plus a count of connections of the app process to Nominatim (must stay 0), plus how many shown places carry an area.
// Run: node tools/tk010_p95.mjs [rounds=2] [out.json]   (login/env as tmp/tk002-live.mjs; Meteor + mongod from run-local-tk010.ps1)
import { createRequire } from 'node:module';
import { readFileSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { execSync } from 'node:child_process';
import { resolve4 } from 'node:dns/promises';

const WebSocket = createRequire(new URL('../app/package.json', import.meta.url))('ws');
const env = Object.fromEntries(readFileSync(new URL('../.env', import.meta.url), 'utf8').split(/\r?\n/).map(l => l.match(/^([A-Z_][A-Z0-9_]*)=(.*)$/)).filter(Boolean).map(m => [m[1], m[2]]));
const rounds = Number(process.argv[2] ?? 2), outFile = process.argv[3] ?? 'C:/verger-data/pilot/tk010/p95.json';
const CITIES = ['Barcelona', 'Paris', 'Madrid', 'Rome', 'Stockholm', 'Edinburgh', 'Chicago', 'Dublin', 'London', 'New York'];

const netstat = () => execSync('netstat -ano -p tcp', { encoding: 'utf8' });
const pid = netstat().split(/\r?\n/).map(l => l.trim().split(/\s+/)).find(c => c[3] === 'LISTENING' && c[1]?.endsWith(':3200'))?.[4];
const ips = new Set(await resolve4('nominatim.openstreetmap.org').catch(() => []));
let seenNom = 0, polls = 0;
const poll = setInterval(() => {
  polls++;
  for (const l of netstat().split(/\r?\n/)) { const c = l.trim().split(/\s+/); if (c[4] === pid && ips.has((c[2] ?? '').split(':')[0])) seenNom++; }
}, 250);

const ws = new WebSocket('ws://127.0.0.1:3200/websocket');
let id = 0; const pending = new Map();
const call = (method, ...params) => new Promise((res, rej) => { const i = String(++id); pending.set(i, { res, rej }); ws.send(JSON.stringify({ msg: 'method', method, params, id: i })); });
ws.on('message', d => { const m = JSON.parse(d); if (m.msg === 'ping') ws.send('{"msg":"pong"}'); if (m.msg === 'result') { const p = pending.get(m.id); pending.delete(m.id); m.error ? p.rej(new Error(m.error.reason || m.error.error)) : p.res(m.result); } });
await new Promise(r => ws.on('open', r));
ws.send(JSON.stringify({ msg: 'connect', version: '1', support: ['1'] }));
await new Promise(r => setTimeout(r, 500));
<class 'dict'> ['n', 'cities_complete_points', 'after', 'vs_tk009', 'incomplete_points']

